/** Shapes of spec/spec.json (generated by tools/build_all.py from spec/spec_data.py). */

export interface Para {
  kind: "p" | "li";
  text: string;
}

export interface Requirement {
  id: string;
  group: string;
  category: string;
  text: string;
  rationale: string;
  priority: string;
  input?: string;
  output?: string;
  module?: string;
  design_element: string;
  diagrams: string[];
  impl_path: string;
  verification: string;
  acceptance: string;
  tests: string[];
  source?: string;
  target_status?: string;
  status: string;
}

export interface Module {
  id: string;
  name: string;
  package: string;
  responsibilities: string[];
  interface: string[];
  inputs: string;
  outputs: string;
  dependencies: string;
  errors: string[];
  tests: string[];
  requirements: string[];
}

export interface TestCase {
  id: string;
  level: string;
  type: string;
  title: string;
  requirements: string[];
  preconditions: string;
  steps: string;
  expected: string;
  pass_criterion: string;
  status: string;
  executed_by: string;
  date: string;
  actual: string;
  notes: string;
}

export interface OpenItem {
  id: string;
  issue: string;
  impact: string;
  proposed_handling: string;
  status: string;
  owner: string;
  resolution: string;
  updated: string;
}

export interface Risk {
  id: string;
  risk: string;
  likelihood: string;
  impact: string;
  mitigation: string;
  owner: string;
}

export interface Phase {
  id: string;
  content: string;
  weeks: string;
  start: string;
  end: string;
  depends_on: string[];
  deliverables: string;
  exit_criterion: string;
  kind: "phase" | "sprint" | "buffer";
}

export interface Milestone {
  id: string;
  title: string;
  date: string;
}

export interface Diagram {
  id: string;
  title: string;
  section: string;
  rendered: string;
  mermaid: string[];
  drawio: string[];
  sources_note: string;
}

export interface Screen {
  id: string;
  name: string;
  purpose: string;
  requirements: string;
  design_decisions: string;
  states: string;
}

export interface Wireframe {
  id: string;
  screen: string;
  screen_name: string;
  title: string;
  supports: string[];
  notes: string[];
  image: string;
}

export interface PaperTable {
  provenance: "Paper-reported";
  file: string;
  notes: string[];
  columns: string[];
  rows: Record<string, string>[];
}

export type Row = Record<string, string>;

export interface Spec {
  schema: string;
  meta: {
    code_name: string;
    repo: string;
    title: string;
    identifier: string;
    version: string;
    date: string;
    status: string;
    team: { name: string; roll: string }[];
    guide: string;
    institution: string;
    paper: { title: string; authors: string };
    callouts: Record<string, string>;
  };
  narrative: Record<string, Para[]>;
  paper_results: {
    provenance: "Paper-reported";
    source: string;
    caption: string;
    columns: string[];
    rows: Row[];
    notes: string[];
  };
  fr: Requirement[];
  nfr: Requirement[];
  modules: Module[];
  tests: TestCase[];
  test_strategy: Row[];
  open_items: OpenItem[];
  risks: Risk[];
  schedule: Phase[];
  milestones: Milestone[];
  diagrams: Diagram[];
  screens: Screen[];
  wireframes: Wireframe[];
  tables: Record<string, Row[]>;
  paper_reference: Record<string, PaperTable>;
  counts: Record<string, unknown>;
}

/** Inline content of the paper: text (bold/italic/sup/sub) or MathML. */
export interface Seg {
  t?: string;
  m?: string;
  b?: boolean;
  i?: boolean;
  v?: "sup" | "sub";
}

export type PaperBlock =
  | { type: "title" | "authors" | "affil" | "email" | "abstract" | "keywords" | "h1" | "h2" | "p" | "li" | "ref"; runs: Seg[] }
  | { type: "equation"; math: string; number: string }
  | { type: "figure"; src: string; caption: Seg[] }
  | { type: "table"; label?: string; caption?: Seg[]; rows: Seg[][][] };

export interface Paper {
  provenance: "Paper-reported";
  file: string;
  blocks: PaperBlock[];
}

export interface Slide {
  n: number;
  title: string;
  groups: { text: string; level: number }[][];
  tables: string[][][];
  notes: string;
}

export interface Content {
  spec: Spec;
  mermaid: Record<string, string>;
  files: { path: string; bytes: number }[];
  paper: Paper | null;
  presentation: { file: string; slides: Slide[] } | null;
}
